using System;\nusing System.Collections.Generic;\nusing System.Threading;\nusing System.Threading.Tasks;\nusing Microsoft.Extensions.Logging;\n\nnamespace MagnumOpus.Backend\n{\n    public record Transaction(string Id, string From, string To, decimal Amount, string Token, DateTime Timestamp);\n\n    public interface IBlockchainGateway\n    {\n        Task<string> BroadcastAsync(Transaction tx, CancellationToken ct = default);\n        Task<bool> VerifyAsync(string txHash, CancellationToken ct = default);\n    }\n\n    public class MockBlockchainGateway : IBlockchainGateway\n    {\n        private readonly ILogger<MockBlockchainGateway> _log;\n        public MockBlockchainGateway(ILogger<MockBlockchainGateway> log) => _log = log;\n        public async Task<string> BroadcastAsync(Transaction tx, CancellationToken ct = default)\n        {\n            await Task.Delay(100, ct);\n            var hash = $\"0x{Guid.NewGuid():N}\";\n            _log.LogInformation(\"Broadcast mock tx {Id} => {Hash}\", tx.Id, hash);\n            return hash;\n        }\n        public async Task<bool> VerifyAsync(string txHash, CancellationToken ct = default)\n        {\n            await Task.Delay(50, ct);\n            return true;\n        }\n    }\n\n    public class TransactionProcessor\n    {\n        private readonly IBlockchainGateway _gateway;\n        private readonly ILogger<TransactionProcessor> _log;\n        private readonly SemaphoreSlim _semaphore = new(5); // limit concurrent broadcasts\n\n        public TransactionProcessor(IBlockchainGateway gateway, ILogger<TransactionProcessor> log)\n        {\n            _gateway = gateway ?? throw new ArgumentNullException(nameof(gateway));\n            _log = log ?? throw new ArgumentNullException(nameof(log));\n        }\n\n        public async Task<string> ProcessAsync(Transaction tx, CancellationToken ct = default)\n        {\n            if (tx == null) throw new ArgumentNullException(nameof(tx));\n            Validate(tx);\n            await _semaphore.WaitAsync(ct);\n            try\n            {\n                var hash = await _gateway.BroadcastAsync(tx, ct);\n                var verified = await _gateway.VerifyAsync(hash, ct);\n                if (!verified)\n                {\n                    _log.LogWarning(\"Transaction {Id} failed verification\", tx.Id);\n                    throw new InvalidOperationException(\"Verification failed\");\n                }\n                _log.LogInformation(\"Transaction {Id} processed with hash {Hash}\", tx.Id, hash);\n                return hash;\n            }\n            finally\n            {\n                _semaphore.Release();\n            }\n        }\n\n        private void Validate(Transaction tx)\n        {\n            if (string.IsNullOrWhiteSpace(tx.From)) throw new ArgumentException(\"From address required\");\n            if (string.IsNullOrWhiteSpace(tx.To)) throw new ArgumentException(\"To address required\");\n            if (tx.Amount <= 0) throw new ArgumentException(\"Amount must be positive\");\n            if (string.IsNullOrWhiteSpace(tx.Token)) throw new ArgumentException(\"Token symbol required\");\n        }\n    }\n}\n